// swift-tools-version: 6.0
import PackageDescription

let package = Package(
    name: "InventoryCLI",
    targets: [
        .target(name: "Inventory")
    ]
)

import Foundation

final class UsageCounter {
    var total = 0

    func record() {
        total += 1
    }
}

@main
struct InventoryCLI {
    static func main() {
        let counter = UsageCounter()
        counter.record()
        print("records: \(counter.total)")
    }
}
